var p5jsLib = document.createElement('script');
p5jsLib.setAttribute('src', 'https://cdnjs.cloudflare.com/ajax/libs/p5.js/0.4.2/p5.min.js');

// The p5.js sketch will be executed after the library has been loaded
p5jsLib.onload = function() {var myp5 = new p5(sketch);};

// Add the script to the <iframe>
document.body.appendChild(p5jsLib);

// Hide the original canvas used for non p5.js sketches
var originalCanvas = document.getElementById("pjsComplexSketch");
//originalCanvas.style.display = "none";

/*
 * Here is where the fun starts
 */
var sketch = function(p) {
    // p5.js preload function
    p.preload = function() {

    };


    var canvasWidth = 240;
    var canvasHeight = 480;


    var totalShapes =11;
    var shapes = [];

    var shapesWidth=60;
    var shapesHeight=canvasHeight/(totalShapes-2);
    var numberOfColumns=canvasWidth/shapesWidth;

    var colorMap = [[33,140,141],
                    [108,206,203],
                    [249,229,89],
                    [239,113,38],
                    [142,220,157],
                    [71,62,63]];

    var totalColors = colorMap.length;
    var needsDelay = false;

    // p5.js setup function
    p.setup = function() {
        var canvas = p.createCanvas(canvasWidth, canvasHeight);

        // Do not remove this line, it's necessary to set the sketch window size
        size(canvas.width, canvas.height + 20);

        p.noStroke();
        initShapes();
    };

    // The p5.js draw function
    p.draw = function() {
        p.translate(0,(canvasHeight/2)+shapesHeight);
        p.background(244,232,214);
        drawRepeatedShapes();
        automatic();
    };



function automatic(){

    if(!haveAllShapesAnimationEnded()){

        needsDelay=true;
        return;
    }

    if(needsDelay){
        wait(500);
        needsDelay=false;
    }

    var n = round(random(12));
    console.log(n);
    switch(n){
        case 5:
            if(random(10)<5)
                animateShapes(6,round(random(3,15)));
            break;
        case 6:
            if(random(10)<5)
                animateShapes(6,round(random(15,50)));
            break;
        case 7:
            if(random(10)<5)
                animateShapes(6,round(random(3,15)));
            break;
        case 8:
            if(random(10)<5)
                animateShapes(6,round(random(15,50)));
            break;
        case 9:
            if(random(10)<4){
                var y = -1 * (totalShapes/2) * (shapesHeight*2);
                for(var i=0;i<totalShapes;i++){
                    shapes[i].changeOffsetY(y);
                    y+=(shapesHeight*2);
                }      
            }
            break;
        case 10:


                var y = -1 * (totalShapes/2) * (shapesHeight);
                for(var i=0;i<totalShapes;i++){
                    shapes[i].changeOffsetY(y);
                    y+=(shapesHeight);
                }  

            break;
        case 11:
            animateOddShapes(1);
            animateEvenShapes(2);
            break;
        case 12:
            animateOddShapes(2);
            animateEvenShapes(1);
            break;
        default: animateShapes(n);
    }
}

function wait(seconds){
    var t=millis();
    while(seconds>millis()-t){
        //delay time to wait
    }
}

function initShapes(){
    var y = -1 * (totalShapes/2) * shapesHeight;

    for(var i=0;i<totalShapes;i++){

        shapes.push(new MyShape());
        shapes[i].initShape(shapesWidth,y);

        shapes[i].ci = i%totalColors;

        y+=shapesHeight;
    }
}

function drawRepeatedShapes(){
    var inverted;
    //for each column
    for(var i = 0 ; i < numberOfColumns ; i++){
        inverted = i%2==0 ? true:false;
        drawShapes(i*shapesWidth,
            0,
            inverted);
    }
}

function drawShapes(_offsetX,_offsetY,_inverse){

    for(var i = 0 ; i < shapes.length ; i++){
        shapes[i].update();
        shapes[i].offsetX = _offsetX;
        shapes[i].inverse = _inverse;
        shapes[i].draw();
    }
}


function animateShapes(numberOfAnimation, r){

    generalAnimateShapes(numberOfAnimation,0,1,r);
}

function animateEvenShapes(numberOfAnimation){
    generalAnimateShapes(numberOfAnimation,1,2,0);
}

function animateOddShapes(numberOfAnimation){
    generalAnimateShapes(numberOfAnimation,0,2,0);
}

function generalAnimateShapes(numberOfAnimation,start,interval){
    var r = random(1,40);
    for(var i=start;i<totalShapes;i+=interval){
        shapes[i].startAnimation(numberOfAnimation,r);
    }
}

function haveAllShapesAnimationEnded(){
    var resul = true;
    for(var i=0;i<totalShapes;i++){
        resul = resul && shapes[i].hasEndPrevAnimation();
    }
    return resul;
}

function MyShape (){
    var x1,x2,x3,x4;
    var y1,y2,y3,y4;
    var offsetX,offsetY;
    var c; //color variable;
    var ci;//color index
    var shapeWidth;
    var shapeHeight;
    var leftShapeHeight;
    var inverse; //boolean var to draw shape inverse.

    //General easing objects duration.
    var generalDuration;

    this.initShape = function(_shapeWidth,  posY){
        this.c = color(255);
        this.ci =0;
        this.generalDuration = 10.0;

        this.shapeWidth = _shapeWidth;
        this.x1=0; this.x2=0;
        this.y1 = new EasingInOutValue(); this.y1.setStartValue(this.shapeWidth/2);
        this.y2 = new EasingInOutValue(); this.y2.setStartValue(this.shapeWidth/2);
        this.y3 = new EasingInOutValue(); this.y3.setStartValue(this.shapeWidth/2);
        this.y4 = new EasingInOutValue(); this.y4.setStartValue(this.shapeWidth/2);

        this.shapeHeight = new EasingInOutValue(); this.shapeHeight.setValues(0.0,this.generalDuration);
        this.changeShapeHeight(5,0);
        this.leftShapeHeight = 5.0;
        this.x3=this.shapeWidth;this.x4=this.shapeWidth;

        this.offsetY = new EasingInOutValue(); this.offsetY.setValues(posY,this.generalDuration);
        this.offsetX=0;
        this.inverse=false;
    }

    this.changeShapeHeight = function(h){
        this.shapeHeight.setNextValues(h,this.generalDuration);
        this.shapeHeight.startAnimation();
    }

    this.changeOffsetY = function(_offsetY){
        this.offsetY.setNextValues(_offsetY,20.0);
        this.offsetY.startAnimation();
    }

    this.setOffsets = function (x,y){
        this.offsetX = x;
        this.offsetY = y;
    }

    this.startAnimation = function(numberOfAnimation,r){
        if(this.hasEndPrevAnimation()){
            switch(numberOfAnimation){
                case 0:
                    this.y3.setNextValues(this.y1.easingValue , 15);
                    this.y4.setNextValues(this.y2.easingValue , 15);
                    this.y3.startAnimation();
                    this.y4.startAnimation();
                    break;
                case 1:
                    this.y3.setNextValues(this.y1.easingValue + this.shapeWidth, 15);
                    this.y4.setNextValues(this.y2.easingValue + this.shapeWidth, 15);
                    this.y3.startAnimation();
                    this.y4.startAnimation();
                    break;
                case 2:
                    this.y3.setNextValues(this.y1.easingValue - this.shapeWidth, 15);
                    this.y4.setNextValues(this.y2.easingValue - this.shapeWidth, 15);
                    this.y3.startAnimation();
                    this.y4.startAnimation();
                    break;
                case 3:
                    this.y3.setNextValues(this.y1.easingValue - this.shapeWidth, 15);
                    this.y4.setNextValues(this.y2.easingValue + this.shapeWidth, 15);
                    this.y3.startAnimation();
                    this.y4.startAnimation();
                    break;
                case 4:
                    this.y3.setNextValues(this.y1.easingValue + this.shapeWidth, 15);
                    this.y4.setNextValues(this.y2.easingValue - this.shapeWidth, 15);
                    this.y3.startAnimation();
                    this.y4.startAnimation();
                    break;
                case 5:
                    this.shapeHeight.setNextValues(r, 15.0);
                    this.shapeHeight.startAnimation();
                    break;
                case 6:
                    this.y1.setNextValues(r, 15);
                    this.y2.setNextValues(-r, 15);
                    this.y1.startAnimation();
                    this.y2.startAnimation();
                    break;
            }
        }
    }

    this.hasEndPrevAnimation = function(){
        return this.y1.end &&
        this.y2.end && this.y3.end && this.y4.end &&
        this.shapeHeight.end && this.offsetY.end;
    }

    this.update = function(){
        this.y1.update();
        this.y2.update();
        this.y3.update();
        this.y4.update();
        this.shapeHeight.update();
        this.offsetY.update();
    }

    this.draw = function(){
        p.fill(colorMap[this.ci][0] ,
             colorMap[this.ci][1] ,
             colorMap[this.ci][2] ,
             130);

        p.push();
        p.translate(this.offsetX,this.offsetY.easingValue);
        p.beginShape();
        if(!this.inverse){

            p.vertex(this.x1,this.y1.easingValue+this.shapeHeight.easingValue);
            p.vertex(this.x3,this.y3.easingValue+this.shapeHeight.easingValue);
            p.vertex(this.x4,this.y4.easingValue-this.shapeHeight.easingValue);
            p.vertex(this.x2,this.y2.easingValue-this.shapeHeight.easingValue);

        }else{

            p.vertex(this.x1+this.shapeWidth,this.y1.easingValue+this.shapeHeight.easingValue);
            p.vertex(this.x3-this.shapeWidth,this.y3.easingValue+this.shapeHeight.easingValue);
            p.vertex(this.x4-this.shapeWidth,this.y4.easingValue-this.shapeHeight.easingValue);
            p.vertex(this.x2+this.shapeWidth,this.y2.easingValue-this.shapeHeight.easingValue);
        }
        p.endShape();
        p.pop();
    }


}

function EasingInOutValue(){
    //easing variables
    var easingValue;
    var startValue;
    var endValue;
    var change;
    var duration;
    var animationTime;
    //boolean variables
    var end;
    var start;



    this.setStartValue = function(_startVal){
        this.startValue = _startVal;
        this.easingValue = this.startValue;
        this.defaultRestarts();
    }

    this.setValues = function(_startVal, _endVal, _duration){
        this.startValue = _startVal;
        this.easingValue = this.startValue;
        this.endValue = _endVal;
        this.duration = _duration;
        this.defaultRestarts();
    }

    //run this when object already has a start value.
    this.setNextValues = function(_endVal,_duration){
        this.startValue = this.easingValue;
        this.endValue = _endVal;
        this.duration = _duration;
        this.defaultRestarts();
    }

    this.defaultRestarts = function(){
        this.animationTime = 0;
        this.end = true;
        this.start = false;
        this.change = abs(this.startValue - this.endValue);
        this.change *= this.endValue < this.easingValue ? -1:1;
    }

    this.calcEasingInOut = function(){
        this.easingValue = this.easeInOut(this.animationTime,
            this.startValue,
            this.change,
            this.duration);
    }

    this.easeInOut = function( t,  b,  c,  d) {
        return -c / 2 * ( cos(3.1415926535* t / d) - 1) + b;
    }

    this.update = function(){
        if(round(this.easingValue) == round(this.endValue)){
            this.end = true;

        }

        if(!this.end && this.start){

            this.animationTime+=0.1;
            this.calcEasingInOut();
        }
    }

    this.startAnimation = function(){
        this.end = false;
        this.start = true;
    }

}

};
